              ref: vm => void (this.comp = vm as ComponentPublicInstance),
            })
          : null
      },
      mounted() {
        // this call runs while Comp is currentInstance, but
        // the effect for this `$watch` should nonetheless be registered with Child
        this.comp!.$watch(
          () => this.show,
